#include "map_authoring.h"
#include <QRegularExpression>
#include <functional>
namespace cf {
static char cell(const QByteArray&b,int i){return i>=0&&i<b.size()?b[i]:0;}
World &areaAt(Project&p,int i){return i?p.areas[i-1]:p.world;}
QString uniqueMapId(QString base,const QStringList&used){base=base.toLower();base.replace(QRegularExpression("[^a-z0-9_]+"),"_");base=base.left(24);if(base.isEmpty())base="object";if(base[0].isDigit())base.prepend('_');QString id=base;for(int i=2;used.contains(id);++i)id=base+"_"+QString::number(i);return id;}
static bool position(const World&w,QPoint tile,MapSelection selected,QString &error){if(tile.x()<0||tile.y()<0||tile.x()>=w.width||tile.y()>=w.height){error="Place inside the map.";return false;}for(auto&o:w.objects)if(!(selected.kind=="object"&&selected.id==o.id)&&QPoint(o.x,o.y)==tile){error="An object already occupies this tile.";return false;}for(auto&a:w.actors)if(!(selected.kind=="npc"&&selected.id==a.id)&&QPoint(a.x,a.y)==tile){error="A character already occupies this tile.";return false;}if(selected.kind!="player"&&tile==QPoint(w.spawnX,w.spawnY)){error="Keep the player spawn clear.";return false;}return true;}
bool moveMapInstance(Project&p,int index,const MapSelection&s,QPoint tile,QString&error){auto&w=areaAt(p,index);if(!position(w,tile,s,error))return false;if(s.kind=="object"){for(auto&o:w.objects)if(o.id==s.id){if(o.solid&&cell(w.collision,tile.y()*w.width+tile.x())){error="A solid object cannot be placed on painted collision.";return false;}o.x=tile.x();o.y=tile.y();return true;}}else if(s.kind=="npc"||s.kind=="player"){auto collision=w.effectiveCollision();if(cell(collision,tile.y()*w.width+tile.x())){error="Choose a walkable tile for a character or player.";return false;}if(s.kind=="player"){w.spawnX=tile.x();w.spawnY=tile.y();return true;}for(auto&a:w.actors)if(a.id==s.id){a.x=tile.x();a.y=tile.y();return true;}}error="Select an existing instance.";return false;}
static void rewriteTarget(QString&source,QString kind,QString oldArea,QString oldId,QString newArea,QString newId){QRegularExpression reference("(^[ \t]*"+kind+"[ \t]+)"+QRegularExpression::escape(oldArea)+"([ \t]+)"+QRegularExpression::escape(oldId)+"(?=[ \t]+(?:interact|hit|defeat)\\b)",QRegularExpression::MultilineOption);source.replace(reference,"\\1"+newArea+"\\2"+newId);}
bool placeMapInstance(Project&p,int index,const MapBrush&brush,QPoint tile,MapSelection&selection,QString&error){auto&w=areaAt(p,index);if(!position(w,tile,{},error))return false;WorldObject object;Actor actor;QString sourceTileset;bool isObject=false,found=false;
if(brush.kind=="object"||brush.kind=="npc"){for(auto&area:p.allAreas())if(area.id==brush.area){if(brush.kind=="object")for(auto&o:area.objects)if(o.id==brush.id){object=o;sourceTileset=area.tileset;isObject=found=true;}if(brush.kind=="npc")for(auto&a:area.actors)if(a.id==brush.id){actor=a;found=true;}}}
else if(brush.kind=="library"){for(auto&n:p.npcs)if(n.id==brush.id){actor=n.actor;actor.libraryId=n.id;actor.name=n.name;found=true;}}
else if(brush.kind=="sprite"){if(auto a=p.asset(brush.id)){if(a->kind=="sprite"){actor.name=a->name;actor.id=a->name;actor.sprite=a->id;actor.script="behavior idle\nspeed 1\nevery 1\n";found=true;}}}
else if(brush.kind=="new_object"||brush.kind=="container"){isObject=found=true;object.name=brush.kind=="container"?"Container":"Object";object.id=object.name;object.kind=brush.kind=="container"?"storage":"script";object.storage=brush.kind=="container"?"inventory":QString();object.tile=brush.id.toInt();}
if(!found){error="Choose a sprite, library character or existing object to place.";return false;}
if(isObject){if(w.objects.size()>=8){error="This area supports up to 8 objects.";return false;}if(!sourceTileset.isEmpty()&&sourceTileset!=w.tileset){error="This object uses another tileset. Choose the source tileset or an object from this tileset.";return false;}auto ts=p.asset(w.tileset);if(!ts||object.tile<0||object.tile>=ts->tileCount()){error="Choose an area tileset and a valid graphic tile first.";return false;}QStringList ids;for(auto&o:w.objects)ids<<o.id;QString oldId=object.id;object.id=uniqueMapId(object.id,ids);if(brush.kind=="object"){rewriteTarget(object.onInteract,"object",brush.area,oldId,w.id,object.id);rewriteTarget(object.onHit,"object",brush.area,oldId,w.id,object.id);}object.x=tile.x();object.y=tile.y();if(object.solid&&cell(w.collision,object.y*w.width+object.x)){error="Choose a tile without painted collision for a solid object.";return false;}if(brush.kind=="container"){if(p.storages.size()>=8){error="Use up to 8 storages. Reuse an existing container or remove unused storage first.";return false;}QStringList storageIds;for(auto&s:p.storages)storageIds<<s.id;object.storage=uniqueMapId(object.id+"_storage",storageIds);p.storages<<Storage{object.storage,object.name,8,{}};}w.objects<<object;selection={"object",object.id};}
else{if(w.actors.size()>=4){error="This area supports up to 4 sprite characters.";return false;}auto sprite=p.asset(actor.sprite);if(!sprite||sprite->kind!="sprite"){error="This character needs an available sprite.";return false;}int tiles=sprite->frameTileCount();if(auto a=p.asset(w.player))tiles+=a->frameTileCount();for(auto&a:w.actors)if(auto image=p.asset(a.sprite))tiles+=image->frameTileCount();if(tiles>40){error="These sprites exceed the Game Boy's 40 hardware sprites per frame.";return false;}if(cell(w.effectiveCollision(),tile.y()*w.width+tile.x())){error="Choose a walkable tile for this character.";return false;}QStringList ids;for(auto&a:w.actors)ids<<a.id;QString oldId=actor.id;actor.id=uniqueMapId(actor.id.isEmpty()?actor.name:actor.id,ids);if(brush.kind=="npc")for(auto*source:{&actor.onInteract,&actor.onHit,&actor.onDefeat})rewriteTarget(*source,"npc",brush.area,oldId,w.id,actor.id);actor.x=tile.x();actor.y=tile.y();w.actors<<actor;selection={"npc",actor.id};}return true;}
static void eachEvent(Project&p,const std::function<void(QString&)>&fn){for(auto&s:p.scenes){fn(s.onSceneEnter);fn(s.onBack);for(auto&e:s.elements)fn(e.actions);}for(auto&n:p.prompts){fn(n.onEnter);for(auto&c:n.choices)fn(c.actions);}for(auto&s:p.scripts)fn(s.source);for(auto&t:p.timers)fn(t.source);for(auto&i:p.items)fn(i.useScript);auto actor=[&](Actor&a){fn(a.onInteract);fn(a.onHit);fn(a.onDefeat);};for(auto&n:p.npcs)actor(n.actor);for(int i=0;i<p.allAreas().size();++i){auto&w=areaAt(p,i);fn(w.onStart);for(auto&o:w.objects){fn(o.onInteract);fn(o.onHit);}for(auto&a:w.actors)actor(a);for(auto&e:w.terrainEvents)fn(e.script);}}
bool renameMapInstance(Project&p,int index,const MapSelection&s,QString id,QString&error){if(!QRegularExpression("^[A-Za-z_][A-Za-z0-9_]{0,31}$").match(id).hasMatch()){error="Use 1–32 letters, numbers or underscores; start with a letter or underscore.";return false;}auto&w=areaAt(p,index);QString *target=nullptr;if(s.kind=="object")for(auto&o:w.objects){if(o.id==id&&o.id!=s.id){error="Another object uses this target ID.";return false;}if(o.id==s.id)target=&o.id;}if(s.kind=="npc")for(auto&a:w.actors){if(a.id==id&&a.id!=s.id){error="Another character uses this target ID.";return false;}if(a.id==s.id)target=&a.id;}if(!target){error="Select an object or character.";return false;}QString area=w.id;*target=id;QRegularExpression reference("(^[ \\t]*"+s.kind+"[ \\t]+"+QRegularExpression::escape(area)+"[ \\t]+)"+QRegularExpression::escape(s.id)+"(?=[ \\t]+(?:interact|hit|defeat)\\b)",QRegularExpression::MultilineOption);eachEvent(p,[&](QString&source){source.replace(reference,"\\1"+id);});return true;}
bool removeMapInstance(Project&p,int index,const MapSelection&s){auto&w=areaAt(p,index);if(s.kind=="object")for(int i=0;i<w.objects.size();++i)if(w.objects[i].id==s.id){w.objects.removeAt(i);return true;}if(s.kind=="npc")for(int i=0;i<w.actors.size();++i)if(w.actors[i].id==s.id){w.actors.removeAt(i);return true;}return false;}
static int createMapImpl(Project&p,QString name,QString scene,QString parentMap,int source,int width,int height,QString tileset,QString player,bool contents,QString&error){if(p.allAreas().size()>=8){error="Use up to 8 areas in a project.";return -1;}if(name.trimmed().isEmpty()||width<20||width>64||height<18||height>64){error="Name the map and choose a size from 20×18 to 64×64 tiles.";return -1;}if(parentMap.isEmpty()&&p.maps.size()>=32){error="Use up to 32 map groups.";return -1;}if(parentMap.isEmpty()&&scene.isEmpty()&&p.scenes.size()>=32){error="Use up to 32 scenes.";return -1;}
if(!parentMap.isEmpty()){bool found=false;for(auto&m:p.maps)if(m.id==parentMap)found=true;if(!found){error="Choose an existing parent map.";return -1;}}else if(!scene.isEmpty()&&(p.sceneIndex(scene)<0||p.scenes[p.sceneIndex(scene)].kind!="world")){error="Choose a world scene.";return -1;}
World w;if(source>=0&&source<p.allAreas().size())w=p.allAreas()[source];else{w.tiles.fill(0);w.collision.fill(0);w.spawnX=w.spawnY=2;w.actors.clear();w.objects.clear();}w.name=name.trimmed();w.tileset=tileset;w.player=player;w.exits.clear();w.onStart.clear();if(!contents){w.actors.clear();w.objects.clear();w.interactions.clear();w.terrainEvents.clear();}if(contents){for(auto&o:w.objects)if(o.x>=width||o.y>=height){error="Some objects fall outside this size. Enlarge the map or turn off Copy contents.";return -1;}for(auto&a:w.actors)if(a.x>=width||a.y>=height){error="Some characters fall outside this size. Enlarge the map or turn off Copy contents.";return -1;}}w.resize(width,height);QStringList ids;for(auto&a:p.allAreas())ids<<a.id;QString sourceId=w.id;w.id=uniqueMapId("area_"+name,ids);if(contents&&source>=0){auto fix=[&](QString&code){for(auto&o:w.objects)rewriteTarget(code,"object",sourceId,o.id,w.id,o.id);for(auto&a:w.actors)rewriteTarget(code,"npc",sourceId,a.id,w.id,a.id);};for(auto&o:w.objects){fix(o.onInteract);fix(o.onHit);}for(auto&a:w.actors){fix(a.onInteract);fix(a.onHit);fix(a.onDefeat);}for(auto&e:w.terrainEvents)fix(e.script);}if(parentMap.isEmpty()){if(scene.isEmpty()){ids.clear();for(auto&s:p.scenes)ids<<s.id;Scene s{uniqueMapId("scene_"+name,ids),name};s.kind="world";scene=s.id;p.scenes<<s;}ids.clear();for(auto&m:p.maps)ids<<m.id;MapGroup m{uniqueMapId("map_"+name,ids),name,scene};p.maps<<m;parentMap=m.id;}w.mapId=parentMap;
if(!w.tileset.isEmpty())if(auto a=p.asset(w.tileset))for(auto&t:w.tiles)if(t>=a->tileCount())t=0;w.spawnX=qBound(0,w.spawnX,w.width-1);w.spawnY=qBound(0,w.spawnY,w.height-1);auto collision=w.effectiveCollision();if(cell(collision,w.spawnY*w.width+w.spawnX)){bool found=false;for(int y=0;y<w.height&&!found;++y)for(int x=0;x<w.width;++x)if(!cell(collision,y*w.width+x)){w.spawnX=x;w.spawnY=y;found=true;break;}if(!found){error="The template has no walkable spawn tile.";return -1;}}
p.areas<<w;auto owner=p.sceneIndex(p.areaScene(w.id));if(owner>=0&&p.scenes[owner].kind=="world"&&p.scenes[owner].startArea.isEmpty())p.scenes[owner].startArea=w.id;return p.areas.size();}
int createMap(Project&p,QString name,QString scene,QString parentMap,int source,int width,int height,QString tileset,QString player,bool contents,QString&error){auto copy=p;int result=createMapImpl(copy,name,scene,parentMap,source,width,height,tileset,player,contents,error);if(result>=0)p=copy;return result;}

}
